import {projectRole} from './role.js?v=4.0.0';
import {developmentProfile} from './progression.js?v=4.0.0';
import {MOMENT_MODES} from './career-moments.js?v=4.0.0';
export const escapeHTML=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeHTML;
export function momentPreferences(s){return `<label class="moment-preference" for="moment-mode">Interruptions de simulation<select id="moment-mode" ${s.retired?'disabled':''}>${MOMENT_MODES.map(([id,name])=>`<option value="${id}" ${s.v40.moments.mode===id?'selected':''}>${name}</option>`).join('')}</select></label><p class="muted">Les décisions obligatoires mettent toujours la simulation en pause. Votre destination reste conservée.</p>`;}
export function momentsView(s,limit=80){const rows=s.v40.moments.history.slice(-limit).reverse();return `<section class="panel v40-moments"><p class="eyebrow">LES MOMENTS QUI COMPTENT</p><h3>Temps forts</h3>${rows.length?rows.map(e=>`<article class="moment"><small>S${e.season} · J${e.day-(e.season-1)*365}</small><h4>${esc(e.title)}</h4><p>${esc(e.text)}</p></article>`).join(''):'<p class="muted">Votre prochain temps fort apparaîtra ici.</p>'}</section>`;}
export function roleView(s){const q=projectRole(s,s.hero,s.team),p=s.players.find(p=>p.id===s.hero);return `<section class="panel role-card"><p class="eyebrow">VOTRE PLACE DANS L’ÉQUIPE</p><h3>${esc(s.role)}</h3><div class="role-minute">${s.minutes}<small>minutes projetées</small></div><p>${p.injury?'Indisponible pendant '+p.injury+' jours.':p.returning?'Reprise progressive après blessure.':'Temps de jeu ajusté selon vos performances et la concurrence.'}</p><div class="role-factors">${[['Niveau',q.level],['Concurrent direct',q.rival],['Forme récente',Math.round(q.form)],['Confiance',Math.round(s.trust)],['Maîtrise du système',Math.round(s.system)]].map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}</div><p class="muted">${esc(s.roleReason||'Projection indicative : les fautes, la fatigue et le déroulement du match influencent le temps réellement joué.')}</p></section>`;}
export function progressionView(s){const p=s.players.find(p=>p.id===s.hero),profile=developmentProfile(p),last=s.v40.training.history.at(-1);return `<section class="panel"><p class="eyebrow">DÉVELOPPEMENT</p><h3>${esc(typeof profile==='string'?profile:profile.label||profile.profile||'Votre profil')}</h3><p>Votre spécialisation vient de vos attributs. La progression ralentit aux niveaux élevés ; les qualités physiques évoluent avec l’âge.</p>${last?`<p>Dernière séance · jour ${last.day} : ${Object.entries(last.amounts||{}).map(([k,v])=>esc(k)+' +'+Math.round(v)+' XP').join(' · ')}</p>`:'<p class="muted">Effectuez une séance pour consulter vos gains réels.</p>'}</section>`;}
